CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

// Kernel: one block per (batch, head). Each block tiles over [d_head, d_state] output.
// Dimensions: B=batch, H=n_heads, C=chunk_count, L=block_len, P=d_head, N=d_state
// X_blocks: [B, C, L, H, P]  contiguous
// A_blocks: [B, H, C, L]     contiguous  (already permuted)
// B_blocks: [B, C, L, H, N]  contiguous
// initial_state: [B, H, P, N] or empty (numel==0 means no initial state)
// output: [B, H, P, N]

// We tile the P x N output: each warp handles a row of P (one p index), iterating over N.
// For typical P=N=64: 64 warps, each accumulating 64 floats.
// blockDim = (32, WARPS_PER_BLOCK) where WARPS_PER_BLOCK covers d_head rows.

#define MAX_BLOCK_LEN 64
#define WARPS_PER_BLOCK 8

__global__ void mamba2_final_state_kernel(
    const float* __restrict__ X_blocks,  // [B, C, L, H, P]
    const float* __restrict__ A_blocks,  // [B, H, C, L]
    const float* __restrict__ B_blocks,  // [B, C, L, H, N]
    const float* __restrict__ initial_state, // [B, H, P, N] or nullptr
    float* __restrict__ output,           // [B, H, P, N]
    int B, int H, int C, int L, int P, int N,
    bool has_initial_state
) {
    // blockIdx.x = b * H + h
    int bh = blockIdx.x;
    int b = bh / H;
    int h = bh % H;

    // Each thread handles one (p, n) pair
    // threadIdx.x = n index, threadIdx.y = p index
    int n = threadIdx.x;  // 0..N-1
    int p = threadIdx.y;  // 0..P-1 (tiled if P > blockDim.y)

    // We may need to tile over p if P > blockDim.y
    // With blockDim.y = WARPS_PER_BLOCK and P=64, we tile ceil(P/WARPS_PER_BLOCK) times

    // Shared memory for A_blocks chunk data: [C, L]
    // We'll load chunk by chunk
    extern __shared__ float smem[];
    // smem layout: [L] for A values of current chunk (loaded by thread 0 of each warp)
    // Actually let all threads in a row share the A scan for that chunk
    // smem: float a_scan[L] per chunk, reloaded each chunk iteration
    float* a_smem = smem; // size L, broadcast to all threads

    // Strides
    // X_blocks: [B, C, L, H, P] -> stride b: C*L*H*P, c: L*H*P, l: H*P, h: P, p: 1
    // A_blocks: [B, H, C, L]    -> stride b: H*C*L, h: C*L, c: L, l: 1
    // B_blocks: [B, C, L, H, N] -> stride b: C*L*H*N, c: L*H*N, l: H*N, h: N, n: 1

    int X_stride_b = C * L * H * P;
    int X_stride_c = L * H * P;
    int X_stride_l = H * P;
    // h,p: X_blocks[b,c,l,h,p] = X_blocks[b*X_stride_b + c*X_stride_c + l*X_stride_l + h*P + p]

    int A_stride_b = H * C * L;
    int A_stride_h = C * L;
    // A_blocks[b,h,c,l] = A_blocks[b*A_stride_b + h*A_stride_h + c*L + l]

    int B_stride_b = C * L * H * N;
    int B_stride_c = L * H * N;
    int B_stride_l = H * N;
    // B_blocks[b,c,l,h,n] = B_blocks[b*B_stride_b + c*B_stride_c + l*B_stride_l + h*N + n]

    int out_stride_b = H * P * N;
    int out_stride_h = P * N;
    // output[b,h,p,n] = output[b*out_stride_b + h*out_stride_h + p*N + n]

    const float* A_bh = A_blocks + (long long)b * A_stride_b + (long long)h * A_stride_h;
    const float* X_bh = X_blocks + (long long)b * X_stride_b + h * P;
    const float* B_bh = B_blocks + (long long)b * B_stride_b + h * N;

    // Each thread accumulates its (p,n) output across all chunks and tokens
    float acc = 0.0f;

    // Compute total prefix last: sum of all chunk last-cumsum values
    // chunk_totals[c] = A_cumsum[b,h,c,-1] = sum_{l=0}^{L-1} A_blocks[b,h,c,l]
    // chunk_prefix[c] = sum_{c'=0}^{c-1} chunk_totals[c']  (exclusive)
    // chunk_weight[c] = exp(chunk_prefix_total - chunk_prefix[c])
    //   where chunk_prefix_total = sum of all chunk_totals

    // First pass: compute all chunk_totals and total_prefix
    // We store chunk_totals in shared memory temporarily
    // Use smem as chunk_totals[C] then prefix
    // Do this with threadIdx.x==0 && threadIdx.y==0
    float* chunk_totals_smem = smem + L; // after a_smem [L], store [C] chunk totals

    if (threadIdx.x == 0 && threadIdx.y == 0) {
        float prefix = 0.0f;
        for (int c = 0; c < C; c++) {
            // cumsum last of chunk c for (b,h)
            float cs = 0.0f;
            for (int l = 0; l < L; l++) {
                cs += A_bh[c * L + l];
            }
            chunk_totals_smem[c] = cs; // store chunk total
        }
    }
    __syncthreads();

    // Now compute total prefix
    float total_prefix;
    if (threadIdx.x == 0 && threadIdx.y == 0) {
        float s = 0.0f;
        for (int c = 0; c < C; c++) s += chunk_totals_smem[c];
        // reuse slot [C] for total
        chunk_totals_smem[C] = s;
    }
    __syncthreads();
    total_prefix = chunk_totals_smem[C];

    // Now iterate chunks, computing exclusive prefix on the fly
    float running_prefix = 0.0f;
    for (int c = 0; c < C; c++) {
        float chunk_total = chunk_totals_smem[c];
        // chunk_weight = exp(total_prefix - running_prefix)
        float chunk_weight = expf(total_prefix - running_prefix);

        // Load A cumsum for this chunk into smem
        if (threadIdx.x == 0 && threadIdx.y == 0) {
            float cs = 0.0f;
            for (int l = 0; l < L; l++) {
                cs += A_bh[c * L + l];
                a_smem[l] = cs;
            }
        }
        __syncthreads();

        float a_cumsum_last = a_smem[L - 1]; // = chunk_total

        // Each thread accumulates for its (p, n) over all l in this chunk
        // decay_l = exp(a_cumsum_last - a_cumsum[l])
        // contribution = chunk_weight * sum_l( decay_l * B[b,c,l,h,n] * X[b,c,l,h,p] )
        if (p < P && n < N) {
            const float* X_c = X_bh + (long long)c * X_stride_c;
            const float* B_c = B_bh + (long long)c * B_stride_c;
            float local_acc = 0.0f;
            for (int l = 0; l < L; l++) {
                float decay_l = expf(a_cumsum_last - a_smem[l]);
                float b_val = B_c[l * B_stride_l + n];  // B[b,c,l,h,n]
                float x_val = X_c[l * X_stride_l + p];  // X[b,c,l,h,p]
                local_acc += decay_l * b_val * x_val;
            }
            acc += chunk_weight * local_acc;
        }
        __syncthreads(); // before a_smem is reused

        running_prefix += chunk_total;
    }

    // Write output
    if (p < P && n < N) {
        long long out_idx = (long long)b * out_stride_b + (long long)h * out_stride_h + p * N + n;
        float val = acc;
        if (has_initial_state) {
            // initial_state[b, h, p, n]
            float total_decay = expf(total_prefix);
            val += total_decay * initial_state[out_idx];
        }
        output[out_idx] = val;
    }
}

torch::Tensor mamba2_final_state_cuda(
    torch::Tensor X_blocks,
    torch::Tensor A_blocks,
    torch::Tensor B_blocks,
