    int smem_size = (L + C + 1) * sizeof(float);

    // Re-implement with p_tile support
    // We'll use a different kernel that takes p_offset from blockIdx.y

    // Actually, relaunch the kernel below that supports p_tile via blockIdx.y
    const float* init_ptr = has_initial_state ? initial_state.data_ptr<float>() : nullptr;

    // Use the tiled kernel
    auto kernel = [&]() {
        // inline lambda not possible for CUDA; we call the kernel defined below
