        const float*, const float*, const float*, const float*,
        float*, int, int, int, int, int, int, int, bool);

    mamba2_final_state_kernel_tiled<<<grid, block, smem_size>>>(
        X_blocks.data_ptr<float>(),
        A_blocks.data_ptr<float>(),
        B_blocks.data_ptr<float>(),
