__global__ void mamba2_final_state_kernel_tiled(
    const float* __restrict__ X_blocks,
    const float* __restrict__ A_blocks,
    const float* __restrict__ B_blocks,
    const float* __restrict__ initial_state,
    float* __restrict__ output,
    int B, int H, int C, int L, int P, int N,
    int p_tile_size,
    bool has_initial_state
