    int b = bh / H;
    int h = bh % H;
    int p_tile = blockIdx.y;
    int p_base = p_tile * p_tile_size;
    int p = p_base + (int)threadIdx.y;
    int n = (int)threadIdx.x;

    extern __shared__ float smem[];
    float* a_smem = smem;              // [L] for current chunk A cumsum
    float* chunk_totals_smem = smem + L; // [C+1] chunk totals + grand total

    int X_stride_b = C * L * H * P;
    int X_stride_c = L * H * P;
    int X_stride_l = H * P;
    int A_stride_b = H * C * L;
    int A_stride_h = C * L;
    int B_stride_c = L * H * N;
    int B_stride_l = H * N;
    int out_stride_b = H * P * N;
    int out_stride_h = P * N;

    const float* A_bh = A_blocks + (long long)b * A_stride_b + (long long)h * A_stride_h;
    const float* X_bh = X_blocks + (long long)b * X_stride_b + h * P;
