            for (int l = 0; l < L; l++) cs += A_bh[c * L + l];
            chunk_totals_smem[c] = cs;
            total += cs;
        }
        chunk_totals_smem[C] = total;
    }
    __syncthreads();

    float total_prefix = chunk_totals_smem[C];
    float acc = 0.0f;
    float running_prefix = 0.0f;

    for (int c = 0; c < C; c++) {
        float chunk_total = chunk_totals_smem[c];
        float chunk_weight = expf(total_prefix - running_prefix);

        // Load A cumsum into smem
