            acc += chunk_weight * local_acc;
        }
        __syncthreads();

        running_prefix += chunk_total;
    }

    if (p < P && n < N) {
        long long out_idx = (long long)b * out_stride_b + (long long)h * out_stride_h + (long long)p * N + n;
        float val = acc;
        if (has_initial_state) {
            float total_decay = expf(total_prefix);
            val += total_decay * initial_state[out_idx];
        }
        output[out_idx] = val;
    }
